import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[] input = readInput(sc);
        int p = input[0];
        int k = input[1];
        final long MOD = 1000000007L;
        long result = 0;
        if (k == 0) {
            result = fastPow(p, p - 1, MOD);
        } else {
            for (int i = 1; i < p; i++) {
                if ((p - 1) % i == 0 && fastPow(k, i, p) == 1) {
                    result = fastPow(p, (p - 1) / i, MOD);
                    if (k == 1) {
                        result = (result * p) % MOD;
                    }
                    break;
                }
            }
        }
        System.out.println(result);
    }

    private static int[] readInput(Scanner sc) {
        String line = sc.nextLine();
        String[] parts = line.trim().split("\\s+");
        int[] nums = new int[2];
        nums[0] = Integer.parseInt(parts[0]);
        nums[1] = Integer.parseInt(parts[1]);
        return nums;
    }

    private static long fastPow(long base, long exp, long mod) {
        long res = 1;
        base = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }
}
